package org.apache.commons.lang;

import junit.framework.TestCase;

public class AgentBRT_Lang_45_raw_diff_Test extends TestCase {

    public void testReproduceBug() {
        String input = "short";
        int lower = 10; // greater than input length
        int upper = 15;
        String appendToEnd = "...";

        // Expected behavior: since lower > input.length(), it should return the whole string
        // without abbreviation, as the fix adjusts lower to input.length().
        String result = WordUtils.abbreviate(input, lower, upper, appendToEnd);

        // In the buggy version, this would incorrectly abbreviate or throw an error.
        assertEquals("short", result);
    }
}

